import hmac
KEY = b"secret-key"

def sign(msg):
    return hmac.new(KEY, msg.encode("utf-8"), "sha256").hexdigest()

def verify(msg, signature):
    return hmac.compare_digest(sign(msg), signature)

import hashlib
import hmac

def hash_pw(pw, salt):
    h = salt + pw.encode("utf-8")
    for _ in range(1000):
        h = hashlib.sha256(h).digest()
    return h.hex()

def check_pw(pw, salt, stored):
    return hmac.compare_digest(hash_pw(pw, salt), stored)
